import (
	"crypto/md5"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
)

type FileEntry struct {
	Data     []byte
	Mimetype string
	Hash     string
}

var files = map[string]FileEntry{}

func main() {
	port := os.Getenv("PORT")
	if port == "" { port = "3000" }

	http.HandleFunc("/upload", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method != "POST" { http.NotFound(w, r); return }
		r.ParseMultipartForm(32 << 20)
		fh, header, _ := r.FormFile("file")
		defer fh.Close()
		data, _ := io.ReadAll(fh)
		hash := md5.Sum(data)
		hashStr := hex.EncodeToString(hash[:])
		files[header.Filename] = FileEntry{Data: data, Mimetype: header.Header.Get("Content-Type"), Hash: hashStr}
		w.WriteHeader(201)
		json.NewEncoder(w).Encode(map[string]interface{}{
			"url":   "https://cdn.example.com/files/" + header.Filename,
			"etag":  hashStr,
			"size":  len(data),
		})
	})

	http.ListenAndServe(":"+port, nil)
	_ = fmt.Sprintf("%s", "")
