  if (!f) { cacheMisses++; return res.status(404).json({ error: 'Not found' }); }
  if (req.headers['if-none-match'] === f.hash) { cacheHits++; return res.status(304).end(); }
  cacheMisses++;
  res.set('Cache-Control', 'public, max-age=3600');
  res.set('ETag', f.hash);
  res.send(f.buffer);
