from fastapi import FastAPI, UploadFile, File, Request
from fastapi.responses import Response
import hashlib, os
app = FastAPI()
port = int(os.getenv('PORT', 3000))
files = {}
cache_hits = 0
cache_misses = 0
@app.post('/upload', status_code=201)
async def upload(file: UploadFile = File(...)):
    data = await file.read()
    h = hashlib.md5(data).hexdigest()
    files[file.filename] = {'data': data, 'mimetype': file.content_type, 'hash': h}
    return {'url': f'https://cdn.example.com/files/{file.filename}', 'etag': h}
@app.get('/files/{name}')
def get_file(name: str, request: Request):
    global cache_hits, cache_misses
    f = files.get(name)
    if not f:
        cache_misses += 1
        return Response(status_code=404)
    if request.headers.get('if-none-match') == f['hash']:
        cache_hits += 1
        return Response(status_code=304)
    cache_misses += 1
    return Response(content=f['data'], media_type=f['mimetype'], headers={'Cache-Control': 'public, max-age=3600', 'ETag': f['hash']})
@app.get('/cdn-status')
def cdn_status():
    total_size = sum(len(f['data']) for f in files.values())
    total = cache_hits + cache_misses
    ratio = round(cache_hits / total, 2) if total else 0
    return {'files': len(files), 'totalSize': total_size, 'cacheHits': cache_hits, 'cacheMisses': cache_misses, 'cacheRatio': ratio}

