package main

import (
	"crypto/md5"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"
	"sync/atomic"
)

type FileEntry struct {
	Data     []byte
	Mimetype string
	Hash     string
}

var files = map[string]FileEntry{}
var cacheHits, cacheMisses int64

func main() {
	port := os.Getenv("PORT")
	if port == "" { port = "3000" }

	http.HandleFunc("/upload", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method != "POST" { http.NotFound(w, r); return }
		r.ParseMultipartForm(32 << 20)
		fh, header, _ := r.FormFile("file")
		defer fh.Close()
		data, _ := io.ReadAll(fh)
		hash := md5.Sum(data)
		hashStr := hex.EncodeToString(hash[:])
		files[header.Filename] = FileEntry{Data: data, Mimetype: header.Header.Get("Content-Type"), Hash: hashStr}
		w.WriteHeader(201)
		json.NewEncoder(w).Encode(map[string]interface{}{"url": "https://cdn.example.com/files/" + header.Filename, "etag": hashStr})
	})

	http.HandleFunc("/files/", func(w http.ResponseWriter, r *http.Request) {
		name := strings.TrimPrefix(r.URL.Path, "/files/")
		f, ok := files[name]
		if !ok {
			atomic.AddInt64(&cacheMisses, 1)
			w.WriteHeader(404)
			return
		}
		if r.Header.Get("If-None-Match") == f.Hash {
			atomic.AddInt64(&cacheHits, 1)
			w.WriteHeader(304)
			return
		}
		atomic.AddInt64(&cacheMisses, 1)
		w.Header().Set("Cache-Control", "public, max-age=3600")
		w.Header().Set("ETag", f.Hash)
		w.Header().Set("Content-Type", f.Mimetype)
		w.Write(f.Data)
	})

	http.HandleFunc("/cdn-status", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		totalSize := 0
		for _, f := range files { totalSize += len(f.Data) }
		hits := atomic.LoadInt64(&cacheHits)
		misses := atomic.LoadInt64(&cacheMisses)
		total := hits + misses
		ratio := 0.0
		if total > 0 { ratio = float64(hits) / float64(total) }
		json.NewEncoder(w).Encode(map[string]interface{}{
			"files":       len(files),
			"totalSize":   totalSize,
			"cacheHits":   hits,
			"cacheMisses": misses,
			"cacheRatio":  fmt.Sprintf("%.2f", ratio),
		})
	})

	http.ListenAndServe(":"+port, nil)
}
